import { flattenObject } from '../utils/flattenObject';

export const resolveFallbackMessages = (
  locale: string,
  defaultLocale: string,
  localMessages: Record<string, Record<string, unknown>>,
  builtMessages: Record<string, Record<string, unknown>> = {}
): Record<string, string> => {
  const built =
    builtMessages[locale] ?? builtMessages[defaultLocale];
  if (built) {
    return flattenObject(built);
  }

  const local =
    localMessages[locale] ?? localMessages[defaultLocale];
  if (local) {
    return flattenObject(local);
  }

  return {};
};
