import { useAuthenticationService } from '../../hooks/useService/UseService';
import { fetchUserMetadata } from '../api_services/userMetadata/userMetadataService';
import type UserMetadata from '../userMetadata/model/UserMetadata';
import { Country } from './headerConfig.types';

export const sortString = (a?: string, b?: string) => ((a || '') < (b || '') ? -1 : 1);

interface CachedUserMetadata {
  metadata: UserMetadata;
  timestamp: number;
}

const USERMETADATA_CACHE = new Map<string, CachedUserMetadata>();
const PENDING_REQUESTS = new Map<string, Promise<UserMetadata | null>>();
const USERMETADATA_CACHE_EXPIRATION = 1000 * 60 * 60 * 24; // 24 hours

export const getUserMetadata = async (selectedCountry: Country): Promise<UserMetadata | null> => {
  const cached = USERMETADATA_CACHE.get(selectedCountry);
  if (cached && cached.timestamp + USERMETADATA_CACHE_EXPIRATION > Date.now()) {
    return cached.metadata;
  }

  const pending = PENDING_REQUESTS.get(selectedCountry);
  if (pending) {
    return pending;
  }

  const request = fetchUserMetadata(selectedCountry).then(userMetadata => {
    if (userMetadata) {
      USERMETADATA_CACHE.set(selectedCountry, { metadata: userMetadata, timestamp: Date.now() });
    }
    PENDING_REQUESTS.delete(selectedCountry);
    return userMetadata || null;
  });

  PENDING_REQUESTS.set(selectedCountry, request);

  return request;
};

export const fetchVendors = async (selectedCountry: Country) => {
  const userMetadata = await getUserMetadata(selectedCountry);
  if (userMetadata?.vendors) return userMetadata.vendors;
  return [];
};

export const getCountriesIntersection = async (newCountries: Country[]): Promise<string[]> => {
  const userCountry = useAuthenticationService().getUserCountry();
  const userMetadata = await getUserMetadata(userCountry || newCountries[0]);

  if (!userMetadata?.supportedCountries) return [];

  return newCountries.filter(newCountry => userMetadata?.supportedCountries?.includes(newCountry));
};
